import { useMemo, useState } from 'react';
import {
  JxBadge,
  JxChip,
  JxButton,
  JxEmptyState,
  JxPagination,
  JxProgressCircle,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'archived';

type Project = {
  id: string;
  name: string;
  used: number;
  quota: number;
  status: ProjectStatus;
};

const STATUS_LABELS: Record<ProjectStatus, string> = {
  active: 'Активен',
  paused: 'На паузе',
  archived: 'В архиве',
};

const STATUS_TONES: Record<ProjectStatus, 'success' | 'warning' | 'default'> = {
  active: 'success',
  paused: 'warning',
  archived: 'default',
};

const STATUSES: ProjectStatus[] = ['active', 'paused', 'archived'];

const PAGE_SIZE = 5;

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Контекст-лаборатория', used: 8200, quota: 10000, status: 'active' },
  { id: 'p2', name: 'Разметка диалогов', used: 3100, quota: 5000, status: 'active' },
  { id: 'p3', name: 'Поисковый индекс', used: 4700, quota: 5000, status: 'paused' },
  { id: 'p4', name: 'Голосовой ассистент', used: 900, quota: 8000, status: 'archived' },
  { id: 'p5', name: 'Генерация отчётов', used: 6400, quota: 12000, status: 'active' },
  { id: 'p6', name: 'Оценка качества', used: 2200, quota: 4000, status: 'paused' },
  { id: 'p7', name: 'Миграция хранилища', used: 11500, quota: 12000, status: 'active' },
  { id: 'p8', name: 'Внутренняя витрина', used: 300, quota: 3000, status: 'archived' },
  { id: 'p9', name: 'Телеметрия прогонов', used: 5600, quota: 7000, status: 'active' },
  { id: 'p10', name: 'Библиотека промптов', used: 1800, quota: 6000, status: 'paused' },
  { id: 'p11', name: 'Сценарии онбординга', used: 4200, quota: 4500, status: 'active' },
];

export default function ProjectQuotaPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>(['active', 'paused']);
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((current) =>
      current.includes(status) ? current.filter((item) => item !== status) : [...current, status],
    );
    setPage(1);
  };

  const removeStatus = (status: ProjectStatus) => {
    setActiveStatuses((current) => current.filter((item) => item !== status));
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses(STATUSES);
    setPage(1);
  };

  const filtered = useMemo(
    () => PROJECTS.filter((project) => activeStatuses.includes(project.status)),
    [activeStatuses],
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const visible = filtered.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  return (
    <section style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {STATUSES.map((status) => {
          const active = activeStatuses.includes(status);
          return (
            <JxChip
              key={status}
              active={active}
              removable={active}
              onRemove={() => removeStatus(status)}
              onClick={() => toggleStatus(status)}
            >
              {STATUS_LABELS[status]}
            </JxChip>
          );
        })}
      </div>

      {filtered.length === 0 ? (
        <JxEmptyState
          title="Под фильтры ничего не подходит"
          message="Снятые статусы скрыли все проекты. Верните фильтры, чтобы увидеть расход."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            {visible.map((project) => (
              <div
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '16px',
                  padding: '12px 16px',
                  background: 'var(--jx-surface)',
                  border: '1px solid var(--jx-border)',
                  borderRadius: 'var(--jx-r)',
                }}
              >
                <JxProgressCircle value={project.used} max={project.quota} showValue />
                <span
                  style={{
                    flex: 1,
                    minWidth: 0,
                    fontFamily: 'var(--jx-font-sans)',
                    color: 'var(--jx-text)',
                  }}
                >
                  {project.name}
                </span>
                <JxBadge tone={STATUS_TONES[project.status]} dot>
                  {STATUS_LABELS[project.status]}
                </JxBadge>
              </div>
            ))}
          </div>

          <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
        </>
      )}
    </section>
  );
}

